div.script:

document.addEventListener('DOMContentLoaded', function() {
    const venueTypeSelect = document.getElementById('venue_type');
    const onlineFields = document.getElementById('online_venue_fields');
    const physicalFields = document.getElementById('physical_venue_fields');
    const countrySelect = document.getElementById('country_id');
    const stateSelect = document.getElementById('state_id');
    const zipCodeInput = document.getElementById('zip_code');
    const eventNameInput = document.getElementById('event_name');
    const dateBeginInput = document.getElementById('date_begin');
    const badgeInput = document.getElementById('badge_image');
    const cardBgInput = document.getElementById('card_bg_image');
    const previewTitle = document.getElementById('event-card-title-preview');
    const previewDate = document.getElementById('event-card-date-preview');
    const previewBg = document.getElementById('event-card-bg-preview');
    const previewBadge = document.getElementById('event-card-badge-preview');

    function toggleVenueFields() {
        const selectedType = venueTypeSelect.value;

        if (selectedType === 'online') {
            onlineFields.style.display = 'block';
            physicalFields.style.display = 'none';
            // Clear physical fields
            document.getElementById('venue_name').value = '';
            document.getElementById('street_address').value = '';
            document.getElementById('city').value = '';
            document.getElementById('zip_code').value = '';
            document.getElementById('state_id').value = '';
        } else {
            onlineFields.style.display = 'none';
            physicalFields.style.display = 'block';
            // Clear online fields
            document.getElementById('online_platform').value = '';
            document.getElementById('online_link').value = '';
        }
    }

    function updateStates() {
        const selectedCountryId = countrySelect.value;
        const stateOptions = stateSelect.querySelectorAll('option');

        // Reset state selection
        stateSelect.value = '';

        // Show/hide states based on selected country
        stateOptions.forEach(option => {
            if (option.value === '') {
                option.style.display = 'block'; // Always show empty option
            } else {
                const stateCountryId = option.getAttribute('data-country');
                if (selectedCountryId && stateCountryId === selectedCountryId) {
                    option.style.display = 'block';
                } else {
                    option.style.display = 'none';
                }
            }
        });

        validateZipCode();
    }

    function validateZipCode() {
        const zipCode = zipCodeInput.value;
        const selectedCountry = countrySelect.options[countrySelect.selectedIndex]?.text;

        if (!zipCode) return; // Don't validate empty ZIP codes

        let isValid = false;
        let errorMessage = '';

        if (selectedCountry === 'United States') {
            // US ZIP code: 12345 or 12345-6789
            isValid = /^\d{5}(-\d{4})?$/.test(zipCode);
            errorMessage = 'US ZIP codes must be in format 12345 or 12345-6789';
        } else if (selectedCountry === 'Canada') {
            // Canadian postal code: A1A 1A1 or A1A1A1
            isValid = /^[A-Za-z]\d[A-Za-z]\s?\d[A-Za-z]\d$/.test(zipCode);
            errorMessage = 'Canadian postal codes must be in format A1A 1A1 or A1A1A1';
        } else {
            // For other countries, basic validation (not empty and reasonable length)
            isValid = zipCode.length >= 3 && zipCode.length <= 10;
            errorMessage = 'Please enter a valid postal code';
        }

        // Visual feedback
        zipCodeInput.classList.toggle('is-invalid', !isValid && zipCode.length > 0);
        zipCodeInput.classList.toggle('is-valid', isValid);

        // Update or create error message
        let errorElement = zipCodeInput.parentNode.querySelector('.invalid-feedback');
        if (!errorElement) {
            errorElement = document.createElement('div');
            errorElement.className = 'invalid-feedback';
            zipCodeInput.parentNode.appendChild(errorElement);
        }
        errorElement.textContent = errorMessage;
    }

    function updatePreviewText() {
        const nameValue = eventNameInput.value.trim();
        const dateValue = dateBeginInput.value.trim();
        previewTitle.textContent = nameValue || 'Event name preview';
        previewDate.textContent = dateValue ? dateValue.replace('T', ' ') : 'Start date preview';
    }

    function updatePreviewImage(input, target, isBackground) {
        const file = input.files && input.files[0];
        if (!file) {
            if (isBackground) {
                target.style.backgroundImage = '';
            } else {
                target.style.display = 'none';
                target.removeAttribute('src');
            }
            return;
        }
        const reader = new FileReader();
        reader.onload = function(evt) {
            if (isBackground) {
                target.style.backgroundImage = `url(${evt.target.result})`;
            } else {
                target.src = evt.target.result;
                target.style.display = 'block';
            }
        };
        reader.readAsDataURL(file);
    }

    // Event listeners
    venueTypeSelect.addEventListener('change', toggleVenueFields);
    countrySelect.addEventListener('change', updateStates);
    stateSelect.addEventListener('change', validateZipCode);
    zipCodeInput.addEventListener('input', validateZipCode);
    eventNameInput.addEventListener('input', updatePreviewText);
    dateBeginInput.addEventListener('input', updatePreviewText);
    badgeInput.addEventListener('change', () => updatePreviewImage(badgeInput, previewBadge, false));
    cardBgInput.addEventListener('change', () => updatePreviewImage(cardBgInput, previewBg, true));

    // Specialty and Case multi-select functionality
    const specialtyTags = document.getElementById('specialty-tags');
    const specialtySelect = document.getElementById('specialty-select');
    const specialtyIdsHidden = document.getElementById('specialty-ids-hidden');

    const caseTags = document.getElementById('case-tags');
    const caseSelect = document.getElementById('case-select');
    const caseIdsHidden = document.getElementById('case-ids-hidden');

    let selectedSpecialties = [];
    let selectedCases = [];

    function createMultiSelect(tagsContainer, select, hiddenInput, selectedItems) {
        // Get all available options from the select element
        const allOptions = Array.from(select.querySelectorAll('option')).filter(opt => opt.value).map(opt => ({
            id: parseInt(opt.value),
            name: opt.textContent
        }));

        function updateSelectOptions() {
            // Clear current options except the placeholder
            select.innerHTML = '<option value="">Select a specialty...</option>';

            // Add available options (not selected)
            allOptions.forEach(option => {
                if (!selectedItems.find(selected => selected.id === option.id)) {
                    const opt = document.createElement('option');
                    opt.value = option.id;
                    opt.textContent = option.name;
                    select.appendChild(opt);
                }
            });
        }

        function updateTags() {
            tagsContainer.innerHTML = '';
            selectedItems.forEach(item => {
                const tag = document.createElement('span');
                tag.className = 'tag';
                tag.innerHTML = `${item.name} <span class="remove-tag" data-id="${item.id}">&times;</span>`;
                tagsContainer.appendChild(tag);
            });
            hiddenInput.value = selectedItems.map(item => item.id).join(',');
        }

        // Initial setup
        updateSelectOptions();
        updateTags();

        // Handle select change
        select.addEventListener('change', () => {
            const selectedId = parseInt(select.value);
            if (selectedId) {
                const selectedOption = allOptions.find(opt => opt.id === selectedId);
                if (selectedOption && !selectedItems.find(item => item.id === selectedId)) {
                    selectedItems.push(selectedOption);
                    updateTags();
                    updateSelectOptions();
                }
            }
            select.value = ''; // Reset to placeholder
        });

        // Handle tag removal
        tagsContainer.addEventListener('click', (e) => {
            if (e.target.classList.contains('remove-tag')) {
                const id = parseInt(e.target.getAttribute('data-id'));
                const index = selectedItems.findIndex(item => item.id === id);
                if (index > -1) {
                    selectedItems.splice(index, 1);
                    updateTags();
                    updateSelectOptions();
                }
            }
        });
    }

    createMultiSelect(specialtyTags, specialtySelect, specialtyIdsHidden, selectedSpecialties);
    createMultiSelect(caseTags, caseSelect, caseIdsHidden, selectedCases);


    // Initialize
    toggleVenueFields();
    updateStates();
    updatePreviewText();
});
